[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Source+Sans+3:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    /* ===== CSS RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Source Sans 3', 'Inter', system-ui, sans-serif;
      color: #2D3748;
      background: #FFFFFF;
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
    }
    h1, h2, h3, h4, h5, h6 { font-family: 'Inter', system-ui, sans-serif; line-height: 1.2; }
    a { text-decoration: none; color: inherit; }
    ul { list-style: none; }
    img { max-width: 100%; height: auto; display: block; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    input { font-family: inherit; }

    /* ===== SKIP LINK ===== */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      background: #C41E3A;
      color: #fff;
      padding: 8px 16px;
      z-index: 10000;
      border-radius: 0 0 4px 4px;
      font-weight: 600;
    }
    .skip-link:focus { top: 0; }

    /* ===== DESIGN TOKENS ===== */
    :root {
      --red: #C41E3A;
      --red-dark: #9E1830;
      --red-light: #F8E0E5;
      --navy: #1B3A5C;
      --navy-dark: #0F2640;
      --navy-light: #E8EEF5;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius: 8px;
      --radius-lg: 12px;
      --transition: 200ms ease;
    }

    /* ===== LAYOUT ===== */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    @media (min-width: 768px) { .container { padding: 0 32px; } }
    @media (min-width: 1024px) { .container { padding: 0 48px; } }

    /* ===== UTILITY BAR ===== */
    .utility-bar {
      background: var(--navy-dark);
      color: rgba(255,255,255,0.85);
      font-size: 13px;
      padding: 6px 0;
    }
    .utility-bar .container {
      display: flex;
      justify-content: flex-end;
      align-items: center;
      gap: 16px;
    }
    .utility-bar a { color: rgba(255,255,255,0.85); transition: color var(--transition); }
    .utility-bar a:hover { color: #fff; }
    .utility-bar .divider { width: 1px; height: 12px; background: rgba(255,255,255,0.25); }

    /* ===== HEADER ===== */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 100;
    }
    .header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Inter', sans-serif;
      font-weight: 800;
      font-size: 18px;
      color: var(--navy);
    }
    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 20px; height: 20px; }
    .nav-desktop { display: none; align-items: center; gap: 28px; }
    .nav-desktop a {
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-700);
      transition: color var(--transition);
      position: relative;
    }
    .nav-desktop a:hover { color: var(--red); }
    .nav-desktop a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--red);
      transition: width var(--transition);
    }
    .nav-desktop a:hover::after { width: 100%; }
    .btn-donate-nav {
      background: var(--red);
      color: #fff;
      padding: 10px 24px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 15px;
      transition: background var(--transition), transform var(--transition);
    }
    .btn-donate-nav:hover { background: var(--red-dark); transform: translateY(-1px); }
    .btn-donate-nav:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }

    /* Hamburger */
    .hamburger {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      width: 44px;
      height: 44px;
      gap: 5px;
      cursor: pointer;
    }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--navy);
      transition: transform 300ms ease, opacity 200ms ease;
    }
    .hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav */
    .mobile-nav {
      position: fixed;
      top: 0;
      right: -100%;
      width: 300px;
      max-width: 85vw;
      height: 100vh;
      background: var(--white);
      z-index: 200;
      padding: 80px 32px 32px;
      transition: right 300ms ease;
      box-shadow: var(--shadow-xl);
    }
    .mobile-nav.open { right: 0; }
    .mobile-nav a {
      display: block;
      padding: 14px 0;
      font-size: 17px;
      font-weight: 500;
      color: var(--gray-700);
      border-bottom: 1px solid var(--gray-100);
      transition: color var(--transition);
    }
    .mobile-nav a:hover { color: var(--red); }
    .mobile-nav .btn-donate-mobile {
      display: block;
      text-align: center;
      background: var(--red);
      color: #fff;
      padding: 14px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 17px;
      margin-top: 20px;
      transition: background var(--transition);
    }
    .mobile-nav .btn-donate-mobile:hover { background: var(--red-dark); }
    .mobile-nav-close {
      position: absolute;
      top: 20px;
      right: 20px;
      width: 44px;
      height: 44px;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }
    .mobile-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.5);
      z-index: 199;
      opacity: 0;
      pointer-events: none;
      transition: opacity 300ms ease;
    }
    .mobile-overlay.active { opacity: 1; pointer-events: auto; }

    @media (min-width: 1024px) {
      .hamburger { display: none; }
      .nav-desktop { display: flex; }
    }

    /* ===== HERO ===== */
    .hero {
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, #2A5A8E 100%);
      color: #fff;
      position: relative;
      overflow: hidden;
      min-height: 520px;
      display: flex;
      align-items: center;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse at 80% 20%, rgba(196,30,58,0.15) 0%, transparent 50%),
        radial-gradient(ellipse at 20% 80%, rgba(255,255,255,0.05) 0%, transparent 50%);
    }
    .hero-pattern {
      position: absolute;
      inset: 0;
      opacity: 0.04;
      background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero .container { position: relative; z-index: 1; padding-top: 64px; padding-bottom: 64px; }
    .hero-content { max-width: 680px; }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(196,30,58,0.2);
      border: 1px solid rgba(196,30,58,0.4);
      color: #FECDD3;
      padding: 6px 16px;
      border-radius: 100px;
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 24px;
    }
    .hero-badge svg { width: 14px; height: 14px; }
    .hero h1 {
      font-size: clamp(32px, 5vw, 52px);
      font-weight: 800;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
      line-height: 1.1;
    }
    .hero p {
      font-size: clamp(16px, 2vw, 19px);
      color: rgba(255,255,255,0.85);
      margin-bottom: 32px;
      max-width: 560px;
      line-height: 1.65;
    }
    .hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }
    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--red);
      color: #fff;
      padding: 14px 32px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 16px;
      transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
    }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
    .btn-primary:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
    .btn-primary svg { width: 18px; height: 18px; }
    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.12);
      color: #fff;
      padding: 14px 32px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 16px;
      border: 1px solid rgba(255,255,255,0.25);
      transition: background var(--transition), border-color var(--transition);
    }
    .btn-secondary:hover { background: rgba(255,255,255,0.2); border-color: rgba(255,255,255,0.4); }
    .btn-secondary:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
    .btn-secondary svg { width: 18px; height: 18px; }

    /* ===== MISSION ===== */
    .mission {
      padding: 80px 0;
      background: var(--white);
    }
    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: var(--red);
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 16px;
    }
    .section-label svg { width: 16px; height: 16px; }
    .mission-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 48px;
      align-items: center;
    }
    @media (min-width: 768px) {
      .mission-grid { grid-template-columns: 1fr 1fr; }
    }
    .mission-text h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 8px;
      letter-spacing: -0.02em;
    }
    .mission-text .mission-highlight {
      font-size: 20px;
      font-weight: 600;
      color: var(--red);
      margin-bottom: 20px;
    }
    .mission-text p {
      color: var(--gray-600);
      font-size: 17px;
      line-height: 1.7;
    }
    .mission-image {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--navy-light) 0%, var(--gray-200) 100%);
    }
    .mission-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      gap: 12px;
    }
    .mission-image-placeholder svg { width: 64px; height: 64px; opacity: 0.5; }
    .mission-image-placeholder span { font-size: 14px; font-weight: 500; }

    /* ===== IMPACT STATS ===== */
    .impact-stats {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 100%);
      color: #fff;
      position: relative;
      overflow: hidden;
    }
    .impact-stats::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 30% 50%, rgba(196,30,58,0.1) 0%, transparent 60%);
    }
    .impact-stats .container { position: relative; z-index: 1; }
    .impact-stats .section-label { color: #FECDD3; }
    .impact-stats .section-label svg { color: #FECDD3; }
    .impact-stats h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .impact-stats > .container > p {
      color: rgba(255,255,255,0.7);
      font-size: 17px;
      margin-bottom: 48px;
      max-width: 560px;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }
    @media (min-width: 768px) {
      .stats-grid { grid-template-columns: repeat(4, 1fr); }
    }
    .stat-card {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      padding: 32px 24px;
      text-align: center;
      transition: background var(--transition), transform var(--transition);
    }
    .stat-card:hover {
      background: rgba(255,255,255,0.12);
      transform: translateY(-2px);
    }
    .stat-icon {
      width: 48px;
      height: 48px;
      background: rgba(196,30,58,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
    }
    .stat-icon svg { width: 24px; height: 24px; color: #FCA5A5; }
    .stat-number {
      font-family: 'Inter', sans-serif;
      font-size: clamp(32px, 4vw, 44px);
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.02em;
      margin-bottom: 4px;
    }
    .stat-label {
      font-size: 14px;
      color: rgba(255,255,255,0.65);
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    /* ===== PROGRAMS ===== */
    .programs {
      padding: 80px 0;
      background: var(--gray-50);
    }
    .programs h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .programs > .container > p {
      color: var(--gray-500);
      font-size: 17px;
      margin-bottom: 40px;
      max-width: 560px;
    }
    .accordion { display: flex; flex-direction: column; gap: 12px; }
    .accordion-item {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: box-shadow var(--transition), border-color var(--transition);
    }
    .accordion-item:hover { border-color: var(--gray-300); }
    .accordion-item.active { border-color: var(--red); box-shadow: 0 0 0 1px var(--red); }
    .accordion-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      width: 100%;
      padding: 20px 24px;
      font-size: 17px;
      font-weight: 600;
      color: var(--navy);
      text-align: left;
      cursor: pointer;
      transition: color var(--transition);
      min-height: 44px;
    }
    .accordion-header:hover { color: var(--red); }
    .accordion-header-left {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .accordion-header-left svg { width: 20px; height: 20px; color: var(--red); flex-shrink: 0; }
    .accordion-chevron {
      width: 20px;
      height: 20px;
      color: var(--gray-400);
      transition: transform 300ms ease, color var(--transition);
      flex-shrink: 0;
    }
    .accordion-item.active .accordion-chevron { transform: rotate(180deg); color: var(--red); }
    .accordion-body {
      max-height: 0;
      overflow: hidden;
      transition: max-height 300ms ease;
    }
    .accordion-body-inner {
      padding: 0 24px 20px 56px;
      color: var(--gray-600);
      font-size: 15px;
      line-height: 1.7;
    }
    .accordion-body-inner a {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--red);
      font-weight: 600;
      margin-top: 12px;
      font-size: 14px;
      transition: gap var(--transition);
    }
    .accordion-body-inner a:hover { gap: 10px; }
    .accordion-body-inner a svg { width: 14px; height: 14px; }

    /* ===== GET INVOLVED ===== */
    .get-involved {
      padding: 80px 0;
      background: var(--white);
    }
    .get-involved h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .get-involved > .container > p {
      color: var(--gray-500);
      font-size: 17px;
      margin-bottom: 40px;
      max-width: 560px;
    }
    .involved-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }
    @media (min-width: 768px) {
      .involved-grid { grid-template-columns: repeat(3, 1fr); }
    }
    .involved-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
    }
    .involved-card:hover {
      border-color: var(--red);
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }
    .involved-card-icon {
      width: 52px;
      height: 52px;
      background: var(--red-light);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }
    .involved-card-icon svg { width: 24px; height: 24px; color: var(--red); }
    .involved-card h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 10px;
    }
    .involved-card p {
      color: var(--gray-600);
      font-size: 15px;
      line-height: 1.65;
      margin-bottom: 20px;
    }
    .btn-outline {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--red);
      font-weight: 600;
      font-size: 15px;
      padding: 10px 0;
      border-bottom: 2px solid transparent;
      transition: border-color var(--transition), gap var(--transition);
    }
    .btn-outline:hover { border-color: var(--red); gap: 10px; }
    .btn-outline svg { width: 16px; height: 16px; }

    /* ===== NEWS ===== */
    .news {
      padding: 80px 0;
      background: var(--gray-50);
    }
    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
      flex-wrap: wrap;
      gap: 16px;
    }
    .news h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.02em;
    }
    .news h2 + p {
      color: var(--gray-500);
      font-size: 17px;
      margin-top: 4px;
    }
    .carousel-controls {
      display: flex;
      gap: 8px;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--gray-300);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition), border-color var(--transition);
      cursor: pointer;
    }
    .carousel-btn:hover { background: var(--gray-100); border-color: var(--gray-400); }
    .carousel-btn:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    .carousel-btn svg { width: 18px; height: 18px; color: var(--gray-600); }
    .carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: var(--white); border-color: var(--gray-300); }
    .news-carousel {
      overflow: hidden;
      position: relative;
    }
    .news-track {
      display: flex;
      transition: transform 400ms ease;
    }
    .news-card-wrapper {
      flex: 0 0 100%;
      padding: 0 12px;
    }
    @media (min-width: 768px) {
      .news-card-wrapper { flex: 0 0 50%; }
    }
    @media (min-width: 1024px) {
      .news-card-wrapper { flex: 0 0 25%; }
    }
    .news-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      height: 100%;
      display: flex;
      flex-direction: column;
      transition: box-shadow var(--transition), transform var(--transition);
    }
    .news-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
    .news-card-image {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, var(--navy-light) 0%, var(--gray-200) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .news-card-image svg { width: 40px; height: 40px; color: var(--gray-300); }
    .news-card-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
    .news-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--red);
      background: var(--red-light);
      padding: 3px 10px;
      border-radius: 100px;
      margin-bottom: 10px;
      width: fit-content;
    }
    .news-card h3 {
      font-size: 17px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 8px;
      line-height: 1.35;
    }
    .news-card p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
      flex: 1;
    }
    .news-card-link {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--red);
      font-weight: 600;
      font-size: 14px;
      margin-top: 14px;
      transition: gap var(--transition);
    }
    .news-card-link:hover { gap: 10px; }
    .news-card-link svg { width: 14px; height: 14px; }
    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 32px;
    }
    .carousel-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--gray-300);
      border: none;
      cursor: pointer;
      transition: background var(--transition), transform var(--transition);
      padding: 0;
    }
    .carousel-dot.active { background: var(--red); transform: scale(1.2); }

    /* ===== DONATE CTA ===== */
    .donate-cta {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
      color: #fff;
      position: relative;
      overflow: hidden;
    }
    .donate-cta::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 70% 30%, rgba(255,255,255,0.08) 0%, transparent 60%);
    }
    .donate-cta .container { position: relative; z-index: 1; }
    .donate-cta-inner {
      display: grid;
      grid-template-columns: 1fr;
      gap: 40px;
      align-items: center;
    }
    @media (min-width: 768px) {
      .donate-cta-inner { grid-template-columns: 1fr 1fr; }
    }
    .donate-cta-text h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }
    .donate-cta-text p {
      font-size: 17px;
      color: rgba(255,255,255,0.85);
      line-height: 1.65;
      margin-bottom: 8px;
    }
    .donate-cta-text .efficiency {
      font-size: 14px;
      color: rgba(255,255,255,0.7);
      font-weight: 600;
    }
    .impact-table {
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-lg);
      overflow: hidden;
    }
    .impact-table-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 16px 24px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .impact-table-row:last-child { border-bottom: none; }
    .impact-table-row:hover { background: rgba(255,255,255,0.05); }
    .impact-amount {
      font-weight: 700;
      font-size: 18px;
      min-width: 70px;
    }
    .impact-desc {
      font-size: 14px;
      color: rgba(255,255,255,0.8);
      flex: 1;
      margin-left: 16px;
    }
    .donate-cta .btn-primary {
      margin-top: 24px;
      background: #fff;
      color: var(--red);
    }
    .donate-cta .btn-primary:hover { background: var(--gray-100); }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--navy-dark);
      color: rgba(255,255,255,0.7);
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 40px 32px;
      margin-bottom: 48px;
    }
    @media (min-width: 768px) {
      .footer-grid { grid-template-columns: repeat(4, 1fr); }
    }
    @media (min-width: 1024px) {
      .footer-grid { grid-template-columns: 2fr 1fr 1fr 1fr 1fr; }
    }
    .footer-brand p {
      font-size: 14px;
      line-height: 1.65;
      margin-top: 12px;
      max-width: 280px;
    }
    .footer-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Inter', sans-serif;
      font-weight: 700;
      font-size: 16px;
      color: #fff;
    }
    .footer-logo-icon {
      width: 32px;
      height: 32px;
      background: var(--red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .footer-logo-icon svg { width: 18px; height: 18px; }
    .footer-col h4 {
      font-size: 13px;
      font-weight: 700;
      color: #fff;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-bottom: 16px;
    }
    .footer-col a {
      display: block;
      font-size: 14px;
      padding: 4px 0;
      color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }
    .footer-col a:hover { color: #fff; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
    }
    .footer-bottom p { font-size: 13px; }
    .footer-social {
      display: flex;
      gap: 12px;
    }
    .footer-social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition);
    }
    .footer-social a:hover { background: rgba(255,255,255,0.15); }
    .footer-social svg { width: 16px; height: 16px; color: rgba(255,255,255,0.7); }

    /* ===== DONATE MODAL ===== */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.6);
      z-index: 500;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 250ms ease;
    }
    .modal-overlay.active { opacity: 1; pointer-events: auto; }
    .modal {
      background: var(--white);
      border-radius: var(--radius-lg);
      max-width: 520px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      transform: translateY(20px) scale(0.97);
      transition: transform 300ms ease;
    }
    .modal-overlay.active .modal { transform: translateY(0) scale(1); }
    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 28px;
      border-bottom: 1px solid var(--gray-200);
    }
    .modal-header h2 {
      font-size: 22px;
      font-weight: 700;
      color: var(--navy);
    }
    .modal-close {
      width: 44px;
      height: 44px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      transition: background var(--transition);
      cursor: pointer;
    }
    .modal-close:hover { background: var(--gray-100); }
    .modal-close svg { width: 20px; height: 20px; color: var(--gray-500); }
    .modal-body { padding: 28px; }
    .modal-body p {
      font-size: 15px;
      color: var(--gray-600);
      margin-bottom: 24px;
      line-height: 1.6;
    }
    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 16px;
    }
    .amount-btn {
      padding: 14px 8px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 17px;
      font-weight: 700;
      color: var(--navy);
      background: var(--white);
      text-align: center;
      cursor: pointer;
      transition: border-color var(--transition), background var(--transition), color var(--transition);
      min-height: 44px;
    }
    .amount-btn:hover { border-color: var(--red); background: var(--red-light); }
    .amount-btn.active { border-color: var(--red); background: var(--red); color: #fff; }
    .amount-btn:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    .custom-amount {
      margin-bottom: 24px;
    }
    .custom-amount label {
      display: block;
      font-size: 13px;
      font-weight: 600;
      color: var(--gray-600);
      margin-bottom: 6px;
    }
    .custom-amount-input-wrap {
      position: relative;
    }
    .custom-amount-input-wrap span {
      position: absolute;
      left: 14px;
      top: 50%;
      transform: translateY(-50%);
      font-size: 17px;
      font-weight: 600;
      color: var(--gray-400);
    }
    .custom-amount-input {
      width: 100%;
      padding: 14px 14px 14px 32px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 17px;
      font-weight: 600;
      color: var(--navy);
      transition: border-color var(--transition);
      min-height: 44px;
    }
    .custom-amount-input:focus { outline: none; border-color: var(--red); }
    .custom-amount-input::placeholder { color: var(--gray-300); font-weight: 400; }
    .donate-frequency {
      display: flex;
      background: var(--gray-100);
      border-radius: var(--radius);
      padding: 4px;
      margin-bottom: 24px;
    }
    .freq-btn {
      flex: 1;
      padding: 10px;
      font-size: 14px;
      font-weight: 600;
      text-align: center;
      border-radius: 6px;
      color: var(--gray-600);
      cursor: pointer;
      transition: background var(--transition), color var(--transition);
      min-height: 44px;
    }
    .freq-btn.active { background: var(--white); color: var(--navy); box-shadow: var(--shadow-sm); }
    .freq-btn:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    .modal-donate-btn {
      display: block;
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: #fff;
      border-radius: var(--radius);
      font-size: 17px;
      font-weight: 700;
      text-align: center;
      cursor: pointer;
      transition: background var(--transition);
      min-height: 44px;
    }
    .modal-donate-btn:hover { background: var(--red-dark); }
    .modal-donate-btn:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    .modal-footer-note {
      text-align: center;
      font-size: 12px;
      color: var(--gray-400);
      margin-top: 16px;
    }

    /* ===== REDUCED MOTION ===== */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
      html { scroll-behavior: auto; }
      .news-track { transition: none !important; }
      .mobile-nav { transition: none !important; }
      .modal { transition: none !important; }
      .modal-overlay { transition: none !important; }
    }

    /* ===== FOCUS VISIBLE ===== */
    :focus { outline: none; }
    :focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }
    button:focus-visible, a:focus-visible { outline: 3px solid var(--red); outline-offset: 2px; }

    /* ===== SCROLLBAR ===== */
    ::-webkit-scrollbar { width: 8px; }
    ::-webkit-scrollbar-track { background: var(--gray-100); }
    ::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 4px; }
    ::-webkit-scrollbar-thumb:hover { background: var(--gray-400); }
  </style>
</head>
<body>

  <!-- Skip Link -->
