  <!-- Main Content -->
  <main id="main-content">

    <!-- Hero -->
    <section class="hero" aria-labelledby="hero-title">
      <div class="hero-pattern" aria-hidden="true"></div>
      <div class="container">
        <div class="hero-content">
          <div class="hero-badge">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
            Active Disaster Response
          </div>
          <h1 id="hero-title">When Disaster Strikes, We're There</h1>
          <p>From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
          <div class="hero-actions">
            <button class="btn-primary" onclick="openDonateModal()">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
              Donate Now
            </button>
            <a href="#volunteer" class="btn-secondary">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
              Become a Volunteer
            </a>
          </div>
        </div>
      </div>
    </section>

    <!-- Mission -->
    <section class="mission" id="about" aria-labelledby="mission-title">
      <div class="container">
        <div class="mission-grid">
          <div class="mission-text">
            <div class="section-label">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              Our Mission
            </div>
            <h2 id="mission-title">Guided by Humanity, Impartiality, and Neutrality</h2>
            <p class="mission-highlight">Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.</p>
            <p>We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most &mdash; regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.</p>
          </div>
