    <!-- Programs -->
    <section class="programs" id="programs" aria-labelledby="programs-title">
      <div class="container">
        <div class="section-label">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>
          Programs &amp; Services
        </div>
        <h2 id="programs-title">How We Make a Difference</h2>
        <p>Our programs span disaster relief, health services, and community resilience &mdash; delivering critical aid when and where it's needed most.</p>

        <div class="accordion" role="tablist">
          <!-- Disaster Relief -->
          <div class="accordion-item">
            <button class="accordion-header" role="tab" aria-expanded="false" aria-controls="panel-disaster" onclick="toggleAccordion(this)">
              <span class="accordion-header-left">
