          <button class="freq-btn active" onclick="selectFrequency(this, 'one-time')" role="radio" aria-checked="true">One-time</button>
          <button class="freq-btn" onclick="selectFrequency(this, 'monthly')" role="radio" aria-checked="false">Monthly</button>
        </div>

        <button class="modal-donate-btn" onclick="handleDonate()">Donate $50</button>
        <p class="modal-footer-note">Secure donation powered by industry-standard encryption. Your data is protected.</p>
      </div>
    </div>
  </div>

  <script>
    /* ===== MOBILE NAV ===== */
    var mobileNavOpen = false;

    function toggleMobileNav() {
      mobileNavOpen ? closeMobileNav() : openMobileNav();
    }

    function openMobileNav() {
      mobileNavOpen = true;
      document.getElementById('mobile-nav').classList.add('open');
      document.querySelector('.mobile-overlay').classList.add('active');
      document.querySelector('.hamburger').classList.add('active');
      document.querySelector('.hamburger').setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }

    function closeMobileNav() {
      mobileNavOpen = false;
      document.getElementById('mobile-nav').classList.remove('open');
      document.querySelector('.mobile-overlay').classList.remove('active');
      document.querySelector('.hamburger').classList.remove('active');
      document.querySelector('.hamburger').setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    /* ===== DONATE MODAL ===== */
    var selectedAmount = 50;
    var selectedFrequency = 'one-time';

    function openDonateModal() {
      document.getElementById('donate-modal').classList.add('active');
      document.body.style.overflow = 'hidden';
      document.querySelector('.modal-close').focus();
    }

    function closeDonateModal() {
      document.getElementById('donate-modal').classList.remove('active');
      document.body.style.overflow = '';
    }

    function selectAmount(btn, amount) {
      selectedAmount = amount;
      document.querySelectorAll('.amount-btn').forEach(function(b) { b.classList.remove('active'); });
      btn.classList.add('active');
      document.getElementById('custom-amount-input').value = '';
      updateDonateBtn();
    }

    function selectFrequency(btn, freq) {
      selectedFrequency = freq;
      document.querySelectorAll('.freq-btn').forEach(function(b) {
        b.classList.remove('active');
        b.setAttribute('aria-checked', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-checked', 'true');
      updateDonateBtn();
    }

    function updateDonateBtn() {
      var label = selectedFrequency === 'monthly' ? 'Donate $' + selectedAmount + '/month' : 'Donate $' + selectedAmount;
      document.querySelector('.modal-donate-btn').textContent = label;
    }

    document.getElementById('custom-amount-input').addEventListener('input', function() {
      var val = this.value.replace(/[^0-9]/g, '');
      this.value = val;
      if (val && parseInt(val) > 0) {
        selectedAmount = parseInt(val);
        document.querySelectorAll('.amount-btn').forEach(function(b) { b.classList.remove('active'); });
        updateDonateBtn();
      }
    });

    function handleDonate() {
      var btn = document.querySelector('.modal-donate-btn');
      btn.textContent = 'Processing...';
      btn.style.opacity = '0.7';
      btn.disabled = true;
      setTimeout(function() {
        btn.textContent = 'Thank you!';
        btn.style.background = '#059669';
        btn.style.opacity = '1';
        setTimeout(function() {
          closeDonateModal();
          btn.style.background = '';
          btn.disabled = false;
          updateDonateBtn();
        }, 1500);
      }, 1000);
    }

    // Close modal on overlay click
    document.getElementById('donate-modal').addEventListener('click', function(e) {
      if (e.target === this) closeDonateModal();
    });

    // Close modal on Escape
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        if (document.getElementById('donate-modal').classList.contains('active')) {
          closeDonateModal();
        }
        if (mobileNavOpen) {
          closeMobileNav();
        }
      }
    });

    /* ===== ACCORDION ===== */
    function toggleAccordion(header) {
      var item = header.parentElement;
      var body = item.querySelector('.accordion-body');
      var inner = body.querySelector('.accordion-body-inner');
      var isActive = item.classList.contains('active');

      // Close all
      document.querySelectorAll('.accordion-item').forEach(function(ai) {
        ai.classList.remove('active');
        ai.querySelector('.accordion-header').setAttribute('aria-expanded', 'false');
        ai.querySelector('.accordion-body').style.maxHeight = '0';
      });

      // Open clicked if it wasn't active
      if (!isActive) {
        item.classList.add('active');
        header.setAttribute('aria-expanded', 'true');
        body.style.maxHeight = inner.scrollHeight + 'px';
      }
    }

    /* ===== NEWS CAROUSEL ===== */
    var carouselIndex = 0;
    var autoplayTimer = null;

    function getCardsPerView() {
      if (window.innerWidth >= 1024) return 4;
      if (window.innerWidth >= 768) return 2;
      return 1;
    }

    function getMaxIndex() {
      var totalCards = 4;
      var perView = getCardsPerView();
      return Math.max(0, totalCards - perView);
    }

    function updateCarousel() {
      var track = document.getElementById('news-track');
      var perView = getCardsPerView();
      var cardWidth = 100 / perView;
      var offset = carouselIndex * cardWidth;
      track.style.transform = 'translateX(-' + offset + '%)';

      // Update dots
      var dots = document.querySelectorAll('.carousel-dot');
      dots.forEach(function(dot, i) {
        dot.classList.toggle('active', i === carouselIndex);
        dot.setAttribute('aria-selected', i === carouselIndex ? 'true' : 'false');
      });

      // Update button states
      document.getElementById('carousel-prev').disabled = carouselIndex <= 0;
      document.getElementById('carousel-next').disabled = carouselIndex >= getMaxIndex();
    }

    function carouselNext() {
      if (carouselIndex < getMaxIndex()) {
        carouselIndex++;
        updateCarousel();
      }
      resetAutoplay();
    }

    function carouselPrev() {
      if (carouselIndex > 0) {
        carouselIndex--;
        updateCarousel();
      }
      resetAutoplay();
    }

    function carouselGoTo(index) {
      carouselIndex = Math.min(index, getMaxIndex());
      updateCarousel();
      resetAutoplay();
    }

    function startAutoplay() {
      autoplayTimer = setInterval(function() {
        if (carouselIndex >= getMaxIndex()) {
          carouselIndex = 0;
        } else {
          carouselIndex++;
        }
        updateCarousel();
      }, 5000);
    }

    function resetAutoplay() {
      clearInterval(autoplayTimer);
      startAutoplay();
    }

    // Handle resize
    window.addEventListener('resize', function() {
      if (carouselIndex > getMaxIndex()) {
        carouselIndex = getMaxIndex();
      }
      updateCarousel();
    });

    /* ===== ANIMATED COUNTERS ===== */
    function animateCounters() {
      var counters = document.querySelectorAll('.stat-number');
      counters.forEach(function(counter) {
        var target = parseInt(counter.getAttribute('data-target'));
        var duration = 2000;
        var startTime = null;

        function formatNumber(num) {
          if (num >= 1000000000) return '$' + (num / 1000000000).toFixed(0) === (num / 1000000000).toString() ? '$' + (num / 1000000000) + 'M' : '$' + (num / 1000000000).toFixed(0) + 'M';
          if (num >= 1000000) return (num / 1000000).toFixed(0) + 'M';
          if (num >= 1000) return (num / 1000).toFixed(0) + 'K';
          return num.toString();
        }

        function step(timestamp) {
          if (!startTime) startTime = timestamp;
          var progress = Math.min((timestamp - startTime) / duration, 1);
          // Ease out cubic
          var eased = 1 - Math.pow(1 - progress, 3);
          var current = Math.floor(eased * target);

          if (target >= 100000000) {
            counter.textContent = '$' + (current / 1000000).toFixed(0) + 'M';
          } else if (target >= 1000000) {
            counter.textContent = (current / 1000000).toFixed(0) + 'M';
          } else if (target >= 1000) {
            counter.textContent = (current / 1000).toFixed(0) + 'K';
          } else {
            counter.textContent = current;
          }

          if (progress < 1) {
            requestAnimationFrame(step);
          } else {
            // Set final value
            if (target >= 100000000) {
              counter.textContent = '$' + (target / 1000000) + 'M';
            } else if (target >= 1000000) {
              counter.textContent = (target / 1000000) + 'M';
            } else if (target >= 1000) {
              counter.textContent = (target / 1000) + 'K';
            } else {
              counter.textContent = target;
            }
          }
        }

        requestAnimationFrame(step);
      });
    }

    // Intersection observer for counter animation
    var statsObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          animateCounters();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    var statsSection = document.querySelector('.impact-stats');
    if (statsSection) statsObserver.observe(statsSection);

    /* ===== INIT ===== */
    updateCarousel();
    startAutoplay();

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
      anchor.addEventListener('click', function(e) {
        var href = this.getAttribute('href');
        if (href === '#') return;
        var target = document.querySelector(href);
        if (target) {
          e.preventDefault();
          var headerHeight = document.querySelector('.header').offsetHeight;
          var targetPosition = target.getBoundingClientRect().top + window.pageYOffset - headerHeight - 16;
          window.scrollTo({ top: targetPosition, behavior: 'smooth' });
        }
      });
    });

    // Touch support for carousel
    (function() {
      var track = document.getElementById('news-track');
      var startX = 0;
      var isDragging = false;

      track.addEventListener('touchstart', function(e) {
        startX = e.touches[0].clientX;
        isDragging = true;
      }, { passive: true });

      track.addEventListener('touchend', function(e) {
        if (!isDragging) return;
        isDragging = false;
        var endX = e.changedTouches[0].clientX;
        var diff = startX - endX;
        if (Math.abs(diff) > 50) {
          if (diff > 0) carouselNext();
          else carouselPrev();
        }
      }, { passive: true });
    })();
  </script>

